        for day in range(23):
            for th,gen, av,si, tag in zip(col_th, col_gen, col_average, col_size, col_day):
                if group_kind == "genotypes":
                    if th_value in gen:
                        if th == 1.9: #take only the ones with normal treatment
                            if tag==day:
                                if si !="nan":
                                    s[day].append(si)
